// ConsistencyTest.kt — Cross-language consistency runner for the Kotlin binding.
//
// Mirrors the Java `java/src/test/java/com/kcl/ConsistencyTest.java` (and the
// go / .NET / nodejs / python runners): execute the hermetic cases from
// `tests/consistency/cases.json` — generated by
// `tests/consistency/generate_cases.py` — and assert the same golden
// expectations, so every language binding is held to one manifest.
//
// Run from the `kotlin` module directory:
//
//     mvn test -Dtest=ConsistencyTest

package com.kcl

import com.fasterxml.jackson.databind.JsonNode
import com.fasterxml.jackson.databind.ObjectMapper
import com.kcl.api.API
import com.kcl.api.Spec.ParseProgramArgs
import com.kcl.api.execProgramArgs
import com.kcl.api.formatCodeArgs
import com.kcl.api.formatTestReportArgs
import com.kcl.api.generateDocArgs
import com.kcl.api.generateKclArgs
import com.kcl.api.generateOpenAPIArgs
import com.kcl.api.generateProtoArgs
import com.kcl.api.generateTomlArgs
import com.kcl.api.parseProgramArgs
import com.kcl.api.pingArgs
import com.kcl.api.testCaseInfo
import com.kcl.api.testResult
import com.kcl.api.validateCodeArgs
import java.nio.file.Files
import java.nio.file.Path
import java.nio.file.Paths
import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Assumptions.assumeTrue
import org.junit.jupiter.api.Test

class ConsistencyTest {
    companion object {
        /** Locate the shared manifest by walking up from the working directory (normally `kotlin/`). */
        private fun locateCasesJson(): Path {
            var dir: Path? = Paths.get("").toAbsolutePath()
            while (dir != null) {
                val candidate = dir.resolve("tests").resolve("consistency").resolve("cases.json")
                if (Files.exists(candidate)) {
                    return candidate
                }
                dir = dir.parent
            }
            throw AssertionError(
                "consistency manifest not found under " + Paths.get("").toAbsolutePath() +
                    ". Run `python tests/consistency/generate_cases.py` to generate it."
            )
        }

        private val CASES_JSON: Path = locateCasesJson()
        private val MAPPER = ObjectMapper()

        /** Repo root: the parent of the parent of the directory holding `cases.json`. */
        private val REPO_ROOT: Path = CASES_JSON.toAbsolutePath().normalize().parent.parent.parent

        @Volatile
        private var manifest: JsonNode? = null

        @Volatile
        private var apiInstance: API? = null

        @Volatile
        private var availableMethods: Set<String>? = null

        private fun manifest(): JsonNode {
            manifest?.let { return it }
            val root = MAPPER.readTree(CASES_JSON.toFile())
            assertEquals(1, root.get("version").asInt(), "unsupported consistency manifest version")
            manifest = root
            return root
        }

        private fun api(): API {
            apiInstance?.let { return it }
            return API().also { apiInstance = it }
        }

        /**
         * Determine the available RPC surface once per run. Cores that predate
         * `BuiltinService.ListMethod` answer with an empty list (or throw), in
         * which case `new_core` cases are skipped.
         */
        private fun methods(): Set<String> {
            availableMethods?.let { return it }
            val names = mutableSetOf<String>()
            try {
                api().listMethod().methodNameListList.forEach { names.add(it) }
            } catch (e: Exception) {
                // treat the RPC surface as unknown
            }
            availableMethods = names
            return names
        }

        private fun skipUnlessSupported(rpc: String) {
            assumeTrue(methods().contains(rpc), "core does not list $rpc (old core)")
        }

        private fun findCase(name: String): JsonNode {
            for (node in manifest().get("cases")) {
                if (node.get("name").asText() == name) {
                    return node
                }
            }
            throw AssertionError("consistency case not found in manifest: $name")
        }

        private fun diff(expected: String, actual: String): String {
            val el = expected.split("\n")
            val al = actual.split("\n")
            val sb = StringBuilder("--- expected\n+++ actual\n")
            var i = 0
            while (i < maxOf(el.size, al.size)) {
                val e = el.getOrNull(i)
                val a = al.getOrNull(i)
                if (e != null && e == a) {
                    sb.append("  ").append(e).append('\n')
                } else {
                    if (e != null) {
                        sb.append("- ").append(e).append('\n')
                    }
                    if (a != null) {
                        sb.append("+ ").append(a).append('\n')
                    }
                }
                i++
            }
            return sb.toString()
        }

        private fun assertField(caseName: String, field: String, expected: String, actual: String) {
            assertEquals(
                expected,
                actual,
                "consistency case `$caseName` field `$field` mismatch:\n" + diff(expected, actual)
            )
        }

        /**
         * Build `ParseProgramArgs` from the manifest. Path entries are pinned
         * repo-relative by `generate_cases.py`; they are resolved against the
         * repository root (the parent of the directory holding cases.json),
         * while absolute entries are kept as-is.
         */
        private fun parseArgs(node: JsonNode): ParseProgramArgs = parseProgramArgs {
            for (path in node.path("paths")) {
                val p = path.asText()
                paths += if (Paths.get(p).isAbsolute) p else REPO_ROOT.resolve(p).toString()
            }
            for (source in node.path("sources")) {
                sources += source.asText()
            }
        }

        private fun textList(node: JsonNode): List<String> =
            (0 until node.size()).map { node.get(it).asText() }

        @Throws(Exception::class)
        private fun runCase(name: String) {
            val c = findCase(name)
            val rpc = c.get("rpc").asText()
            val args = c.get("args")
            val expect = c.get("expect")

            when (rpc) {
                "KclService.Ping" -> {
                    val result = api().ping(pingArgs { value = args.get("value").asText() })
                    assertField(name, "value", expect.get("value").asText(), result.value)
                }
                "KclService.ExecProgram" -> {
                    val execArgs = execProgramArgs {
                        textList(args.get("k_code_list")).forEach { kCodeList += it }
                        if (args.has("overrides")) {
                            textList(args.get("overrides")).forEach { overrides += it }
                        }
                    }
                    val result = api().execProgram(execArgs)
                    if (expect.has("yaml_result")) {
                        assertField(name, "yaml_result", expect.get("yaml_result").asText(), result.yamlResult)
                    }
                    if (expect.has("json_result")) {
                        assertField(name, "json_result", expect.get("json_result").asText(), result.jsonResult)
                    }
                }
                "KclService.FormatCode" -> {
                    val result = api().formatCode(formatCodeArgs { source = args.get("source").asText() })
                    assertField(name, "formatted", expect.get("formatted").asText(), result.formatted.toStringUtf8())
                }
                "KclService.ValidateCode" -> {
                    val result = api().validateCode(
                        validateCodeArgs {
                            code = args.get("code").asText()
                            data = args.get("data").asText()
                        }
                    )
                    assertEquals(
                        expect.get("success").asBoolean(),
                        result.success,
                        "consistency case `$name` field `success`"
                    )
                    if (expect.has("err_message")) {
                        assertField(name, "err_message", expect.get("err_message").asText(), result.errMessage)
                    }
                }
                "KclService.FormatTestReport" -> {
                    skipUnlessSupported(rpc)
                    val infos = args.get("result").get("info").map { info ->
                        testCaseInfo {
                            this.name = info.get("name").asText()
                            error = info.path("error").asText("")
                            duration = java.lang.Long.parseUnsignedLong(info.get("duration").asText())
                            logMessage = info.path("log_message").asText("")
                        }
                    }
                    val result = api().formatTestReport(
                        formatTestReportArgs { this.result = testResult { info += infos } }
                    )
                    assertField(name, "report", expect.get("report").asText(), result.report)
                }
                "KclService.GenerateToml" -> {
                    skipUnlessSupported(rpc)
                    val execArgs = execProgramArgs {
                        textList(args.get("exec_args").get("k_code_list")).forEach { kCodeList += it }
                    }
                    val result = api().generateToml(generateTomlArgs { this.execArgs = execArgs })
                    assertField(name, "toml", expect.get("toml").asText(), result.toml)
                }
                "KclService.GenerateKcl" -> {
                    skipUnlessSupported(rpc)
                    val result = api().generateKcl(
                        generateKclArgs {
                            source = args.get("source").asText()
                            filename = args.get("filename").asText()
                            format = args.get("format").asText()
                        }
                    )
                    assertField(name, "kcl", expect.get("kcl").asText(), result.kcl)
                }
                "KclService.GenerateOpenAPI" -> {
                    skipUnlessSupported(rpc)
                    val result = api().generateOpenAPI(
                        generateOpenAPIArgs {
                            this.parseArgs = parseArgs(args.get("parse_args"))
                            version = args.path("version").asText("")
                        }
                    )
                    assertField(name, "spec", expect.get("spec").asText(), result.spec)
                }
                "KclService.GenerateProto" -> {
                    skipUnlessSupported(rpc)
                    val result = api().generateProto(
                        generateProtoArgs {
                            this.parseArgs = parseArgs(args.get("parse_args"))
                            // `package` is a Kotlin keyword, so the generated DSL
                            // property needs the backtick form.
                            `package` = args.path("package").asText("")
                        }
                    )
                    assertField(name, "proto", expect.get("proto").asText(), result.proto)
                }
                "KclService.GenerateDoc" -> {
                    skipUnlessSupported(rpc)
                    val result = api().generateDoc(
                        generateDocArgs {
                            this.parseArgs = parseArgs(args.get("parse_args"))
                            format = args.path("format").asText("")
                        }
                    )
                    assertField(name, "content", expect.get("content").asText(), result.content)
                }
                else -> throw AssertionError("no runner support for rpc $rpc")
            }
        }
    }

    @Test
    fun testPing() = runCase("ping")

    @Test
    fun testExecProgramBasic() = runCase("exec_program_basic")

    @Test
    fun testExecProgramOverrides() = runCase("exec_program_overrides")

    @Test
    fun testFormatCode() = runCase("format_code")

    @Test
    fun testValidateCodeOk() = runCase("validate_code_ok")

    @Test
    fun testValidateCodeInvalid() = runCase("validate_code_invalid")

    @Test
    fun testGenerateKclJson() = runCase("generate_kcl_json")

    @Test
    fun testGenerateKclYaml() = runCase("generate_kcl_yaml")

    @Test
    fun testGenerateToml() = runCase("generate_toml")

    @Test
    fun testFormatTestReport() = runCase("format_test_report")

    @Test
    fun testGenerateOpenAPIV3() = runCase("generate_openapi_v3")

    @Test
    fun testGenerateProto() = runCase("generate_proto")

    @Test
    fun testGenerateDocMd() = runCase("generate_doc_md")
}
